package dev.bre.engine.trace;

import java.util.List;
import java.util.Optional;

/**
 * One node of an expression's evaluation, for the explanation (LLD §4.12).
 *
 * <p>This is what lets a credit officer see <em>why</em> a rule said what it said: not just
 * "AFF_INDEBTEDNESS_CAP: DEVIATION", but the sub-expression tree with the value at each step, so
 * the ₹30,000 share and the ₹2,00,000 cap are both visible and the arithmetic between them is
 * checkable by eye.
 *
 * <p><b>An explanation is never stored</b> (§4.12). It is regenerated by re-running the engine
 * against the stored facts, the stored {@code bundleHash} and the stored {@code asOf}. Storing one
 * would be storing a derived artefact that could drift from the decision it claims to explain — and
 * it would store fact values in a second place, under different retention.
 *
 * @param src the sub-expression's source text
 * @param span its offsets within the component's expression
 * @param type the BEL type of the value
 * @param value the value as text, or {@code <masked>} or {@code <missing>}
 * @param note something the reader needs, such as a truncated list's real size
 * @param children the sub-expressions, in evaluation order
 */
public record ExprTrace(
    String src,
    Span span,
    String type,
    String value,
    Optional<String> note,
    List<ExprTrace> children) {

  /** What a value reads as when the caller may not see it (§9.4). */
  public static final String MASKED = "<masked>";

  /** What an absent value reads as (§3.5). */
  public static final String MISSING = "<missing>";

  /** §4.12: a list in a trace shows at most this many elements. */
  public static final int MAX_LIST_ELEMENTS = 20;

  /** §4.12: the trace stops at this depth. */
  public static final int MAX_DEPTH = 64;

  /**
   * Where a sub-expression sits in its component's source, as §4.12's {@code [start, end]}.
   *
   * <p>A record rather than an {@code int[]}: an array component would give {@link ExprTrace}
   * reference equality on its span, so two traces of the same evaluation would compare unequal —
   * which is exactly what replay verification does (§4.12 step 3).
   *
   * @param start the first offset, inclusive
   * @param end the last offset, exclusive
   */
  public record Span(int start, int end) {}

  /** Creates a trace node, copying the children. */
  public ExprTrace {
    children = List.copyOf(children);
  }

  /**
   * A leaf node.
   *
   * @param src the source text
   * @param span the offsets
   * @param type the BEL type
   * @param value the rendered value
   * @return the node
   */
  public static ExprTrace leaf(String src, Span span, String type, String value) {
    return new ExprTrace(src, span, type, value, Optional.empty(), List.of());
  }

  /** Whether this node or any descendant was masked. */
  public boolean containsMasked() {
    return MASKED.equals(value) || children.stream().anyMatch(ExprTrace::containsMasked);
  }

  /** How many nodes the whole subtree holds. */
  public int size() {
    return 1 + children.stream().mapToInt(ExprTrace::size).sum();
  }
}
